  Hpe = `Espaços no gráfico (por exemplo, entre %1$s e %2$s FPS) podem ser causados por sincronização vertical (VSync), que sincroniza a apresentação das frames com a frequência de atualização do ecrã para evitar um efeito cortado na imagem ("tearing"). Isto pode fazer com que as amostras se concentrem nos valores de %1$s e %2$s FPS, mesmo quando a taxa média de frames do jogo se situa entre esses valores. Este é um comportamento normal da sincronização vertical e, embora possa afetar a regularidade de apresentação das frames, não causa necessariamente quebras percetíveis na fluidez.`,
